      unread: false, starred: false, important: false, hasAttachment: false,
      draft: true, draftBody: body, draftTo: toEmail,
    });
  });

  // Trash + Spam samples
  push({ id: id(), subject: "You won a FREE cruise!!! (claim now)", messages: [
