export interface Attachment {
  id: string;
  name: string;
  size: string;
  kind: "pdf" | "img" | "doc" | "xls" | "zip" | "slides";
}

export interface Message {
  id: string;
  from: string;
  fromEmail: string;
  to: string[];
  cc?: string[];
  date: number;
  body: string;
  attachments?: Attachment[];
}

export interface Thread {
  id: string;
  subject: string;
  messages: Message[];
  labels: string[];
  category: "primary" | "promotions" | "social" | "updates" | "forums";
  snippet: string;
  unread: boolean;
  starred: boolean;
  important: boolean;
  hasAttachment: boolean;
  draft?: boolean;
  draftBody?: string;
  draftTo?: string;
  snoozedUntil?: number | null;
  archived?: boolean;
  trashed?: boolean;
