function loadThreads(): Thread[] {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Thread[];
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch { /* fresh seed */ }
  return seedThreads();
}

