    case "filter": return <svg {...common} viewBox="0 0 24 24"><path d="M4 5h16l-6 7v6l-4 2v-8L4 5Z" /></svg>;
    case "undo": return <svg {...common} viewBox="0 0 24 24"><path d="M8 5 3 10l5 5M3 10h11a6 6 0 0 1 0 12h-3" /></svg>;
