success.beforeFullFileContent:
:root {
  --bg: #f6f8fc; --panel: #fff; --ink: #1f1f1f; --ink2: #444746; --ink3: #5f6368;
  --line: #e1e3e1; --hover: #f0f4f9; --active: #d3e3fd; --active-ink: #041e49;
  --accent: #0b57d0; --row-h: 44px; --radius: 16px;
  --shadow: 0 1px 2px rgba(60,64,67,.18), 0 4px 14px rgba(60,64,67,.14);
}
[data-theme="dark"] {
  --bg: #1a1c1e; --panel: #232627; --ink: #e3e3e3; --ink2: #c4c7c5; --ink3: #9aa0a6;
  --line: #3c4043; --hover: #2f3336; --active: #39415a; --active-ink: #d3e3fd;
  --accent: #a8c7fa; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 4px 14px rgba(0,0,0,.4);
}
[data-density="cozy"] { --row-h: 38px; }
[data-density="compact"] { --row-h: 32px; }
* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body { margin: 0; font: 14px/1.45 "Google Sans", Roboto, -apple-system, "Segoe UI", sans-serif; background: var(--bg); color: var(--ink); overflow: hidden; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
input, textarea { font: inherit; color: inherit; }
.app { display: flex; flex-direction: column; height: 100%; }

/* Topbar */
.topbar { display: flex; align-items: center; gap: 12px; padding: 8px 16px; }
.tb-left { display: flex; align-items: center; gap: 8px; min-width: 232px; }
.brand { display: flex; align-items: center; gap: 8px; cursor: pointer; }
.brand-name { font-size: 20px; font-weight: 500; color: var(--ink2); white-space: nowrap; }
.search-wrap { flex: 1; max-width: 720px; position: relative; }
.search-box { display: flex; align-items: center; gap: 4px; background: #e9eef6; border-radius: 24px; padding: 2px 8px; }
[data-theme="dark"] .search-box { background: #2f3336; }
.search-box:focus-within { background: var(--panel); box-shadow: var(--shadow); }
.search-box input { flex: 1; border: 0; outline: 0; background: none; padding: 9px 4px; font-size: 15px; min-width: 0; }
.tb-right { margin-left: auto; display: flex; align-items: center; gap: 4px; }
.avatar { width: 32px; height: 32px; border-radius: 50%; color: #fff; display: inline-flex; align-items: center; justify-content: center; font-weight: 600; margin-left: 6px; flex: none; }
.avatar.xs { width: 28px; height: 28px; font-size: 12px; }
.icon-btn { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); flex: none; }
.icon-btn:hover { background: var(--hover); }
.icon-btn:disabled { opacity: .35; cursor: default; background: none; }
.icon-btn.sm { width: 32px; height: 32px; }
.icon-btn.inv { color: #e3e3e3; width: 30px; height: 30px; }
.icon-btn.inv:hover { background: rgba(255,255,255,.15); }

.adv { position: absolute; top: 52px; left: 0; right: 0; background: var(--panel); border-radius: 12px; box-shadow: var(--shadow); padding: 14px 16px; z-index: 60; display: flex; flex-direction: column; gap: 10px; }
.adv-row { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ink2); }
.adv-row span { width: 130px; flex: none; }
.adv-row input { flex: 1; border: 1px solid var(--line); border-radius: 8px; padding: 7px 10px; background: var(--panel); }
.adv-actions { display: flex; justify-content: flex-end; gap: 8px; }

.settings-panel { position: fixed; top: 60px; right: 16px; width: 320px; background: var(--panel); border-radius: 16px; box-shadow: var(--shadow); padding: 18px; z-index: 70; display: flex; flex-direction: column; gap: 12px; }
.settings-panel h3 { margin: 0; font-size: 16px; }
.set-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 13.5px; }
.seg { display: flex; background: var(--hover); border-radius: 20px; padding: 2px; gap: 2px; }
.seg-btn { padding: 5px 10px; border-radius: 16px; font-size: 12px; text-transform: capitalize; color: var(--ink3); }
.seg-btn.on { background: var(--panel); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.2); }
.toggle { width: 40px; height: 22px; border-radius: 12px; background: var(--line); position: relative; transition: .15s; }
.toggle span { position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; transition: .15s; box-shadow: 0 1px 2px rgba(0,0,0,.3); }
.toggle.on { background: var(--accent); }
.toggle.on span { left: 21px; }

/* Layout */
.body { display: flex; flex: 1; min-height: 0; padding: 0 12px 12px 0; gap: 0; }
.sidebar { width: 256px; flex: none; display: flex; flex-direction: column; padding: 0 12px 0 8px; overflow-y: auto; transition: margin .18s; }
.sidebar.collapsed { margin-left: -256px; }
.compose-btn { display: flex; align-items: center; gap: 10px; background: #c2e7ff; color: #001d35; font-weight: 500; border-radius: 16px; padding: 14px 20px; margin: 4px 0 14px 4px; align-self: flex-start; box-shadow: 0 1px 3px rgba(0,0,0,.2); }
[data-theme="dark"] .compose-btn { background: #39415a; color: #d3e3fd; }
.compose-btn:hover { box-shadow: 0 2px 8px rgba(0,0,0,.3); }
.nav { display: flex; flex-direction: column; }
.nav-item { display: flex; align-items: center; gap: 14px; padding: 7px 14px 7px 22px; border-radius: 0 20px 20px 0; color: var(--ink2); font-size: 14px; text-align: left; }
.nav-item:hover { background: var(--hover); }
.nav-item.active { background: var(--active); color: var(--active-ink); font-weight: 600; }
.nav-label { flex: 1; }
.nav-count { font-size: 12px; font-weight: 600; }
.nav-count.dim { opacity: .6; }
.nav-sep { display: flex; align-items: center; justify-content: space-between; padding: 14px 8px 4px 24px; font-size: 13px; color: var(--ink3); font-weight: 500; }
.label-dot { width: 10px; height: 10px; border-radius: 50%; flex: none; }
.storage { margin-top: auto; padding: 16px 8px 8px 22px; font-size: 12px; color: var(--ink3); }
.storage-bar { height: 6px; background: var(--line); border-radius: 4px; overflow: hidden; margin-bottom: 6px; }
.storage-bar span { display: block; height: 100%; background: var(--accent); border-radius: 4px; }

/* Main */
.main { flex: 1; min-width: 0; background: var(--panel); border-radius: var(--radius); display: flex; flex-direction: column; overflow: hidden; }
.cats { display: flex; border-bottom: 1px solid var(--line); overflow-x: auto; }
.cat { display: flex; align-items: center; gap: 10px; padding: 14px 22px 12px; color: var(--ink3); border-bottom: 3px solid transparent; font-size: 14px; font-weight: 500; white-space: nowrap; min-width: 150px; }
.cat em { font-style: normal; font-size: 12px; font-weight: 400; }
.cat:hover { background: var(--hover); }
.cat.active { color: var(--accent); border-bottom-color: var(--accent); }
.toolbar { display: flex; align-items: center; gap: 8px; padding: 6px 14px; border-bottom: 1px solid var(--line); min-height: 48px; position: relative; }
.tb-group { display: flex; align-items: center; gap: 2px; position: relative; }
.tb-group.actions { margin-left: 8px; }
.vdiv { width: 1px; height: 22px; background: var(--line); margin: 0 8px; }
.tb-hint { font-size: 13px; color: var(--ink3); padding-left: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 44vw; }
.tb-right2 { margin-left: auto; display: flex; align-items: center; gap: 2px; }
.page-info { font-size: 12.5px; color: var(--ink3); margin-right: 8px; white-space: nowrap; }
.flip { display: inline-flex; transform: rotate(180deg); }
.flip.r { transform: none; }

.check { position: relative; display: inline-flex; }
.check input { position: absolute; opacity: 0; width: 100%; height: 100%; cursor: pointer; }
.check .box { width: 17px; height: 17px; border: 2px solid var(--ink3); border-radius: 3px; display: inline-flex; align-items: center; justify-content: center; color: var(--accent); background: transparent; }
.check input:checked + .box { border-color: var(--accent); background: var(--accent); color: #fff; }
.check.some .box { border-color: var(--accent); }
.check .dash { width: 9px; height: 2px; background: var(--accent); border-radius: 2px; }

/* Rows */
.list { flex: 1; overflow-y: auto; }
.row { display: flex; align-items: center; gap: 8px; min-height: var(--row-h); padding: 2px 12px 2px 14px; border-bottom: 1px solid var(--line); cursor: pointer; position: relative; background: var(--panel); }
.row:hover { box-shadow: inset 0 0 0 999px var(--hover); }
.row:hover .row-meta { opacity: 0; }
.row.sel { background: #c2e7ff33; box-shadow: inset 0 0 0 999px rgba(194,231,255,.35); }
[data-theme="dark"] .row.sel { box-shadow: inset 0 0 0 999px rgba(168,199,250,.12); }
.row.cursor { box-shadow: inset 2px 0 0 var(--accent); }
.row .sender { width: 190px; flex: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink2); }
.row.unread .sender, .row.unread .subj { font-weight: 700; color: var(--ink); }
.row .subj-snip { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink2); }
.row .subj { color: var(--ink); }
.row.unread { background: color-mix(in srgb, var(--panel) 70%, var(--hover)); }
.subj-snip .snip { color: var(--ink3); }
.pill { font-size: 11px; font-weight: 600; border-radius: 4px; padding: 1px 6px; margin-left: 6px; white-space: nowrap; }
.cat-pill { background: var(--hover); color: var(--ink3); text-transform: capitalize; }
.draft-tag { color: #a50e0e; font-weight: 700; margin-right: 6px; }
.row-meta { display: flex; align-items: center; gap: 8px; flex: none; }
.row-meta .date { font-size: 12.5px; color: var(--ink2); min-width: 64px; text-align: right; }
.row.unread .row-meta .date { font-weight: 700; color: var(--ink); }
.att, .snoozed-ic { color: var(--ink3); display: inline-flex; }
.star, .imp { color: var(--ink3); opacity: .55; display: inline-flex; padding: 2px; border-radius: 50%; flex: none; }
.star:hover, .imp:hover { opacity: 1; background: var(--hover); }
.star.on, .imp.on { opacity: 1; }
.hover-actions { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); display: none; gap: 2px; background: var(--panel); box-shadow: var(--shadow); border-radius: 18px; padding: 2px 6px; }
.row:hover .hover-actions { display: flex; }
.hover-actions button { width: 30px; height: 30px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); }
.hover-actions button:hover { background: var(--hover); }

.empty { text-align: center; padding: 64px 24px; color: var(--ink2); }
.empty h2 { font-size: 20px; font-weight: 400; margin: 18px 0 8px; color: var(--ink); }
.empty p { color: var(--ink3); max-width: 420px; margin: 0 auto 18px; }
.btn { border: 1px solid var(--line); border-radius: 20px; padding: 8px 18px; font-weight: 500; display: inline-flex; align-items: center; gap: 8px; color: var(--accent); background: var(--panel); }
.btn:hover { background: var(--hover); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
[data-theme="dark"] .btn.primary { color: #062e6f; }
.btn.primary:hover { filter: brightness(1.07); }
.btn.ghost { border-color: transparent; }
.btn.danger-ghost { color: #a50e0e; width: 100%; justify-content: center; }
.chip-btn { color: var(--accent); border: 1px solid var(--line); border-radius: 14px; padding: 5px 12px; font-size: 13px; font-weight: 500; display: inline-flex; align-items: center; gap: 6px; }
.chip-btn:hover { background: var(--hover); }

.menu { position: absolute; top: 40px; left: 0; background: var(--panel); border-radius: 10px; box-shadow: var(--shadow); min-width: 230px; padding: 6px 0; z-index: 50; }
.menu.up { top: auto; bottom: 44px; left: 0; }
.menu-title { font-size: 12.5px; color: var(--ink3); padding: 8px 16px 4px; }
.menu-item { display: flex; align-items: center; gap: 10px; width: 100%; text-align: left; padding: 9px 16px; font-size: 14px; }
.menu-item:hover { background: var(--hover); }
.menu-item em { margin-left: auto; font-style: normal; color: var(--ink3); font-size: 12.5px; }

/* Thread */
.thread { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
.thread-head { padding: 18px 24px 10px; display: flex; align-items: flex-start; gap: 12px; }
.thread-head h1 { font-size: 20px; font-weight: 400; margin: 0; flex: 1; min-width: 0; }
.th-labels { display: flex; gap: 2px; flex-wrap: wrap; align-items: center; }
.th-tools { display: flex; align-items: center; gap: 6px; flex: none; }
.msgs { flex: 1; overflow-y: auto; padding: 4px 24px 16px; display: flex; flex-direction: column; gap: 10px; }
.msg { border: 1px solid var(--line); border-radius: 14px; overflow: hidden; background: var(--panel); }
.msg.open { box-shadow: 0 1px 4px rgba(60,64,67,.15); }
.msg-head { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 12px 16px; }
.msg .avatar { width: 36px; height: 36px; font-size: 14px; }
.msg-who { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.msg-who strong { font-size: 14px; }
.msg-to { font-size: 12.5px; color: var(--ink3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg-date { font-size: 12.5px; color: var(--ink3); flex: none; }
.msg-body { padding: 2px 18px 14px 64px; font-size: 14.5px; }
.msg-body p { margin: 0 0 10px; white-space: pre-wrap; overflow-wrap: anywhere; }
.msg-body .quote { border-left: 2px solid var(--line); padding-left: 10px; color: var(--ink3); }
.msg-actions { display: flex; gap: 6px; margin-top: 12px; align-items: center; }
.atts { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 12px; }
.att-card { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px 8px 8px; min-width: 240px; }
.att-ic { color: #fff; font-size: 11px; font-weight: 700; border-radius: 6px; padding: 8px 6px; }
.att-meta { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.att-meta strong { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.att-meta em { font-style: normal; font-size: 12px; color: var(--ink3); }
.reply-bar { display: flex; gap: 10px; padding: 12px 24px 16px; border-top: 1px solid var(--line); }

/* Right rail */
.rail { width: 56px; flex: none; display: flex; flex-direction: column; align-items: center; gap: 4px; padding-top: 8px; position: relative; }
.rail-btn { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); }
.rail-btn:hover, .rail-btn.on { background: var(--hover); color: var(--accent); }
.rail-panel { position: absolute; right: 60px; top: 8px; width: 290px; background: var(--panel); border-radius: 14px; box-shadow: var(--shadow); padding: 14px; z-index: 40; }
.rail-head { display: flex; align-items: center; justify-content: space-between; font-weight: 600; margin-bottom: 10px; }
.minical strong { font-size: 13.5px; }
.cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; margin: 10px 0; text-align: center; font-size: 12px; }
.cal-grid .dow { color: var(--ink3); font-weight: 600; }
.cal-grid .day { padding: 5px 0; border-radius: 50%; }
.cal-grid .day.today { background: var(--accent); color: #fff; font-weight: 700; }
.cal-ev { display: flex; align-items: center; gap: 8px; font-size: 13px; padding: 4px 0; }
.notes { display: flex; flex-direction: column; gap: 8px; }
.note { background: #fef7e0; color: #1f1f1f; border: 1px solid #f0e0b0; border-radius: 8px; padding: 8px 10px; font-size: 13px; display: flex; justify-content: space-between; gap: 6px; align-items: flex-start; }
.task { display: flex; gap: 8px; font-size: 13.5px; align-items: center; }
.task.done { text-decoration: line-through; color: var(--ink3); }

/* Compose */
.composes { position: fixed; right: 76px; bottom: 0; display: flex; gap: 12px; align-items: flex-end; z-index: 80; }
.compose { width: 520px; max-width: calc(100vw - 32px); background: var(--panel); border-radius: 12px 12px 0 0; box-shadow: var(--shadow); display: flex; flex-direction: column; overflow: hidden; max-height: calc(100vh - 80px); }
.compose.max { width: min(860px, calc(100vw - 120px)); }
.compose.min { flex-direction: row; align-items: center; border-radius: 10px; margin-bottom: 12px; padding: 0 6px 0 0; width: 300px; }
.compose-title { flex: 1; text-align: left; padding: 12px 14px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compose-head { background: #f2f6fc; color: var(--ink); display: flex; align-items: center; padding: 6px 6px 6px 14px; font-weight: 500; font-size: 13.5px; }
[data-theme="dark"] .compose-head { background: #2f3336; }
.compose-head span:first-child { flex: 1; }
.compose-head-btns { display: flex; }
.compose-head-btns .icon-btn { color: var(--ink2); }
.compose-fields { padding: 0 4px; position: relative; }
.cf-row { display: flex; align-items: center; border-bottom: 1px solid var(--line); padding: 0 12px; gap: 8px; position: relative; }
.cf-row input { flex: 1; border: 0; outline: 0; padding: 9px 0; background: none; min-width: 0; }
.cc-links { display: flex; gap: 8px; font-size: 13px; }
.cc-links button { color: var(--ink3); }
.cc-links button:hover { color: var(--accent); }
.suggest { position: absolute; left: 8px; right: 8px; top: 40px; }
.compose-body { flex: 1; min-height: 220px; border: 0; outline: 0; resize: none; padding: 12px 16px; background: none; }
.compose.max .compose-body { min-height: 380px; }
.compose-foot { display: flex; align-items: center; gap: 10px; padding: 10px 14px; position: relative; }
.send-split { display: flex; position: relative; }
.send-split .send { border-radius: 20px 0 0 20px; padding: 8px 22px; }
.send-split .caret { border-radius: 0 20px 20px 0; border-left: 1px solid rgba(255,255,255,.4); padding: 8px 10px; }
.fmt-btns { display: flex; gap: 2px; color: var(--ink2); }
.fmt-btns button { width: 30px; height: 30px; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; }
.fmt-btns button:hover { background: var(--hover); }
.draft-note { margin-left: auto; font-size: 12px; color: var(--ink3); }
.suggest { left: 0; right: 0; top: 0; }
.suggest button { display: flex; gap: 10px; align-items: center; width: 100%; text-align: left; padding: 8px 12px; }
.suggest button:hover { background: var(--hover); }
.suggest strong { display: block; font-size: 13.5px; }
.suggest em { display: block; font-style: normal; font-size: 12px; color: var(--ink3); }

/* Toasts + overlay */
.toasts { position: fixed; left: 24px; bottom: 24px; display: flex; flex-direction: column; gap: 8px; z-index: 100; }
.toast { background: #1f1f1f; color: #e3e3e3; border-radius: 8px; padding: 12px 10px 12px 18px; display: flex; align-items: center; gap: 18px; box-shadow: var(--shadow); font-size: 14px; animation: rise .18s ease-out; }
.toast button { color: #a8c7fa; font-weight: 600; padding: 4px 8px; }
@keyframes rise { from { transform: translateY(8px); opacity: 0; } }
.overlay { position: fixed; inset: 0; background: rgba(20,24,28,.45); z-index: 90; display: flex; align-items: center; justify-content: center; padding: 16px; }
.shortcuts { background: var(--panel); border-radius: 16px; padding: 24px 28px; width: 420px; max-width: 100%; box-shadow: var(--shadow); }
.shortcuts h2 { margin: 0 0 14px; font-weight: 500; }
.sc-grid { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; max-height: 50vh; overflow-y: auto; }
.sc-row { display: flex; align-items: center; gap: 14px; font-size: 13.5px; }
kbd { background: var(--hover); border: 1px solid var(--line); border-radius: 6px; padding: 2px 9px; font-family: inherit; font-size: 12.5px; min-width: 52px; text-align: center; }

/* Responsive */
@media (max-width: 1100px) { .rail { display: none; } }
@media (max-width: 860px) {
  .tb-left { min-width: 0; }
  .brand-name { display: none; }
  .hide-sm { display: none; }
  .sidebar { position: fixed; z-index: 85; top: 0; bottom: 0; left: 0; background: var(--bg); padding-top: 64px; box-shadow: var(--shadow); margin-left: -280px; width: 280px; }
  .sidebar.mopen { margin-left: 0; }
  .sidebar.collapsed { margin-left: -280px; }
  .sidebar.collapsed.mopen { margin-left: 0; }
  .body { padding-right: 0; }
  .row .sender { width: 110px; }
  .imp { display: none; }
  .row .subj-snip .snip { display: none; }
  .thread-head, .msgs { padding-left: 14px; padding-right: 14px; }
  .msg-body { padding-left: 14px; }
  .composes { right: 0; left: 0; justify-content: center; }
  .compose { width: 100%; max-width: 100%; border-radius: 0; max-height: 92vh; }
  .tb-hint { max-width: 30vw; }
  .cat em { display: none; }
  .cat { min-width: 0; padding: 12px 14px 10px; }
}
@media print { .topbar, .sidebar, .rail, .toolbar, .reply-bar, .composes, .toasts { display: none !important; } .main { border-radius: 0; } }

success.afterFullFileContent:
:root {
  --bg: #f6f8fc; --panel: #fff; --ink: #1f1f1f; --ink2: #444746; --ink3: #5f6368;
  --line: #e1e3e1; --hover: #f0f4f9; --active: #d3e3fd; --active-ink: #041e49;
  --accent: #0b57d0; --row-h: 44px; --radius: 16px;
  --shadow: 0 1px 2px rgba(60,64,67,.18), 0 4px 14px rgba(60,64,67,.14);
}
[data-theme="dark"] {
  --bg: #1a1c1e; --panel: #232627; --ink: #e3e3e3; --ink2: #c4c7c5; --ink3: #9aa0a6;
  --line: #3c4043; --hover: #2f3336; --active: #39415a; --active-ink: #d3e3fd;
  --accent: #a8c7fa; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 4px 14px rgba(0,0,0,.4);
}
[data-density="cozy"] { --row-h: 38px; }
[data-density="compact"] { --row-h: 32px; }
* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body { margin: 0; font: 14px/1.45 "Google Sans", Roboto, -apple-system, "Segoe UI", sans-serif; background: var(--bg); color: var(--ink); overflow: hidden; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
input, textarea { font: inherit; color: inherit; }
.app { display: flex; flex-direction: column; height: 100%; }

/* Topbar */
.topbar { display: flex; align-items: center; gap: 12px; padding: 8px 16px; }
.tb-left { display: flex; align-items: center; gap: 8px; min-width: 232px; }
.brand { display: flex; align-items: center; gap: 8px; cursor: pointer; }
.brand-name { font-size: 20px; font-weight: 500; color: var(--ink2); white-space: nowrap; }
.search-wrap { flex: 1; max-width: 720px; position: relative; }
.search-box { display: flex; align-items: center; gap: 4px; background: #e9eef6; border-radius: 24px; padding: 2px 8px; }
[data-theme="dark"] .search-box { background: #2f3336; }
.search-box:focus-within { background: var(--panel); box-shadow: var(--shadow); }
.search-box input { flex: 1; border: 0; outline: 0; background: none; padding: 9px 4px; font-size: 15px; min-width: 0; }
.tb-right { margin-left: auto; display: flex; align-items: center; gap: 4px; }
.avatar { width: 32px; height: 32px; border-radius: 50%; color: #fff; display: inline-flex; align-items: center; justify-content: center; font-weight: 600; margin-left: 6px; flex: none; }
.avatar.xs { width: 28px; height: 28px; font-size: 12px; }
.icon-btn { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); flex: none; }
.icon-btn:hover { background: var(--hover); }
.icon-btn:disabled { opacity: .35; cursor: default; background: none; }
.icon-btn.sm { width: 32px; height: 32px; }
.icon-btn.inv { color: #e3e3e3; width: 30px; height: 30px; }
.icon-btn.inv:hover { background: rgba(255,255,255,.15); }

.adv { position: absolute; top: 52px; left: 0; right: 0; background: var(--panel); border-radius: 12px; box-shadow: var(--shadow); padding: 14px 16px; z-index: 60; display: flex; flex-direction: column; gap: 10px; }
.adv-row { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ink2); }
.adv-row span { width: 130px; flex: none; }
.adv-row input { flex: 1; border: 1px solid var(--line); border-radius: 8px; padding: 7px 10px; background: var(--panel); }
.adv-actions { display: flex; justify-content: flex-end; gap: 8px; }

.settings-panel { position: fixed; top: 60px; right: 16px; width: 320px; background: var(--panel); border-radius: 16px; box-shadow: var(--shadow); padding: 18px; z-index: 70; display: flex; flex-direction: column; gap: 12px; }
.settings-panel h3 { margin: 0; font-size: 16px; }
.set-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 13.5px; }
.seg { display: flex; background: var(--hover); border-radius: 20px; padding: 2px; gap: 2px; }
.seg-btn { padding: 5px 10px; border-radius: 16px; font-size: 12px; text-transform: capitalize; color: var(--ink3); }
.seg-btn.on { background: var(--panel); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.2); }
.toggle { width: 40px; height: 22px; border-radius: 12px; background: var(--line); position: relative; transition: .15s; }
.toggle span { position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; transition: .15s; box-shadow: 0 1px 2px rgba(0,0,0,.3); }
.toggle.on { background: var(--accent); }
.toggle.on span { left: 21px; }

/* Layout */
.body { display: flex; flex: 1; min-height: 0; padding: 0 12px 12px 0; gap: 0; }
.sidebar { width: 256px; flex: none; display: flex; flex-direction: column; padding: 0 12px 0 8px; overflow-y: auto; transition: margin .18s; }
.sidebar.collapsed { margin-left: -256px; }
.compose-btn { display: flex; align-items: center; gap: 10px; background: #c2e7ff; color: #001d35; font-weight: 500; border-radius: 16px; padding: 14px 20px; margin: 4px 0 14px 4px; align-self: flex-start; box-shadow: 0 1px 3px rgba(0,0,0,.2); }
[data-theme="dark"] .compose-btn { background: #39415a; color: #d3e3fd; }
.compose-btn:hover { box-shadow: 0 2px 8px rgba(0,0,0,.3); }
.nav { display: flex; flex-direction: column; }
.nav-item { display: flex; align-items: center; gap: 14px; padding: 7px 14px 7px 22px; border-radius: 0 20px 20px 0; color: var(--ink2); font-size: 14px; text-align: left; }
.nav-item:hover { background: var(--hover); }
.nav-item.active { background: var(--active); color: var(--active-ink); font-weight: 600; }
.nav-label { flex: 1; }
.nav-count { font-size: 12px; font-weight: 600; }
.nav-count.dim { opacity: .6; }
.nav-sep { display: flex; align-items: center; justify-content: space-between; padding: 14px 8px 4px 24px; font-size: 13px; color: var(--ink3); font-weight: 500; }
.label-dot { width: 10px; height: 10px; border-radius: 50%; flex: none; }
.storage { margin-top: auto; padding: 16px 8px 8px 22px; font-size: 12px; color: var(--ink3); }
.storage-bar { height: 6px; background: var(--line); border-radius: 4px; overflow: hidden; margin-bottom: 6px; }
.storage-bar span { display: block; height: 100%; background: var(--accent); border-radius: 4px; }

/* Main */
.main { flex: 1; min-width: 0; background: var(--panel); border-radius: var(--radius); display: flex; flex-direction: column; overflow: hidden; }
.cats { display: flex; border-bottom: 1px solid var(--line); overflow-x: auto; }
.cat { display: flex; align-items: center; gap: 10px; padding: 14px 22px 12px; color: var(--ink3); border-bottom: 3px solid transparent; font-size: 14px; font-weight: 500; white-space: nowrap; min-width: 150px; }
.cat em { font-style: normal; font-size: 12px; font-weight: 400; }
.cat:hover { background: var(--hover); }
.cat.active { color: var(--accent); border-bottom-color: var(--accent); }
.toolbar { display: flex; align-items: center; gap: 8px; padding: 6px 14px; border-bottom: 1px solid var(--line); min-height: 48px; position: relative; }
.tb-group { display: flex; align-items: center; gap: 2px; position: relative; }
.tb-group.actions { margin-left: 8px; }
.vdiv { width: 1px; height: 22px; background: var(--line); margin: 0 8px; }
.tb-hint { font-size: 13px; color: var(--ink3); padding-left: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 44vw; }
.tb-right2 { margin-left: auto; display: flex; align-items: center; gap: 2px; }
.page-info { font-size: 12.5px; color: var(--ink3); margin-right: 8px; white-space: nowrap; }
.flip { display: inline-flex; transform: rotate(180deg); }
.flip.r { transform: none; }

.check { position: relative; display: inline-flex; }
.check input { position: absolute; opacity: 0; width: 100%; height: 100%; cursor: pointer; }
.check .box { width: 17px; height: 17px; border: 2px solid var(--ink3); border-radius: 3px; display: inline-flex; align-items: center; justify-content: center; color: var(--accent); background: transparent; }
.check input:checked + .box { border-color: var(--accent); background: var(--accent); color: #fff; }
.check.some .box { border-color: var(--accent); }
.check .dash { width: 9px; height: 2px; background: var(--accent); border-radius: 2px; }

/* Rows */
.list { flex: 1; overflow-y: auto; }
.row { display: flex; align-items: center; gap: 8px; min-height: var(--row-h); padding: 2px 12px 2px 14px; border-bottom: 1px solid var(--line); cursor: pointer; position: relative; background: var(--panel); }
.row:hover { box-shadow: inset 0 0 0 999px var(--hover); }
.row:hover .row-meta { opacity: 0; }
.row.sel { background: #c2e7ff33; box-shadow: inset 0 0 0 999px rgba(194,231,255,.35); }
[data-theme="dark"] .row.sel { box-shadow: inset 0 0 0 999px rgba(168,199,250,.12); }
.row.cursor { box-shadow: inset 2px 0 0 var(--accent); }
.row .sender { width: 190px; flex: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink2); }
.row.unread .sender, .row.unread .subj { font-weight: 700; color: var(--ink); }
.row .subj-snip { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink2); }
.row .subj { color: var(--ink); }
.row.unread { background: color-mix(in srgb, var(--panel) 70%, var(--hover)); }
.subj-snip .snip { color: var(--ink3); }
.pill { font-size: 11px; font-weight: 600; border-radius: 4px; padding: 1px 6px; margin-left: 6px; white-space: nowrap; }
.cat-pill { background: var(--hover); color: var(--ink3); text-transform: capitalize; }
.draft-tag { color: #a50e0e; font-weight: 700; margin-right: 6px; }
.row-meta { display: flex; align-items: center; gap: 8px; flex: none; }
.row-meta .date { font-size: 12.5px; color: var(--ink2); min-width: 64px; text-align: right; }
.row.unread .row-meta .date { font-weight: 700; color: var(--ink); }
.att, .snoozed-ic { color: var(--ink3); display: inline-flex; }
.star, .imp { color: var(--ink3); opacity: .55; display: inline-flex; padding: 2px; border-radius: 50%; flex: none; }
.star:hover, .imp:hover { opacity: 1; background: var(--hover); }
.star.on, .imp.on { opacity: 1; }
.hover-actions { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); display: none; gap: 2px; background: var(--panel); box-shadow: var(--shadow); border-radius: 18px; padding: 2px 6px; }
.row:hover .hover-actions { display: flex; }
.hover-actions button { width: 30px; height: 30px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); }
.hover-actions button:hover { background: var(--hover); }

.empty { text-align: center; padding: 64px 24px; color: var(--ink2); }
.empty h2 { font-size: 20px; font-weight: 400; margin: 18px 0 8px; color: var(--ink); }
.empty p { color: var(--ink3); max-width: 420px; margin: 0 auto 18px; }
.btn { border: 1px solid var(--line); border-radius: 20px; padding: 8px 18px; font-weight: 500; display: inline-flex; align-items: center; gap: 8px; color: var(--accent); background: var(--panel); }
.btn:hover { background: var(--hover); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
[data-theme="dark"] .btn.primary { color: #062e6f; }
.btn.primary:hover { filter: brightness(1.07); }
.btn.ghost { border-color: transparent; }
.btn.danger-ghost { color: #a50e0e; width: 100%; justify-content: center; }
.chip-btn { color: var(--accent); border: 1px solid var(--line); border-radius: 14px; padding: 5px 12px; font-size: 13px; font-weight: 500; display: inline-flex; align-items: center; gap: 6px; }
.chip-btn:hover { background: var(--hover); }

.menu { position: absolute; top: 40px; left: 0; background: var(--panel); border-radius: 10px; box-shadow: var(--shadow); min-width: 230px; padding: 6px 0; z-index: 50; }
.menu.up { top: auto; bottom: 44px; left: 0; }
.menu-title { font-size: 12.5px; color: var(--ink3); padding: 8px 16px 4px; }
.menu-item { display: flex; align-items: center; gap: 10px; width: 100%; text-align: left; padding: 9px 16px; font-size: 14px; }
.menu-item:hover { background: var(--hover); }
.menu-item em { margin-left: auto; font-style: normal; color: var(--ink3); font-size: 12.5px; }

/* Thread */
.thread { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
.thread-head { padding: 18px 24px 10px; display: flex; align-items: flex-start; gap: 12px; }
.thread-head h1 { font-size: 20px; font-weight: 400; margin: 0; flex: 1; min-width: 0; }
.th-labels { display: flex; gap: 2px; flex-wrap: wrap; align-items: center; }
.th-tools { display: flex; align-items: center; gap: 6px; flex: none; }
.msgs { flex: 1; overflow-y: auto; padding: 4px 24px 16px; display: flex; flex-direction: column; gap: 10px; }
.msg { border: 1px solid var(--line); border-radius: 14px; overflow: hidden; background: var(--panel); }
.msg.open { box-shadow: 0 1px 4px rgba(60,64,67,.15); }
.msg-head { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 12px 16px; }
.msg .avatar { width: 36px; height: 36px; font-size: 14px; }
.msg-who { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.msg-who strong { font-size: 14px; }
.msg-to { font-size: 12.5px; color: var(--ink3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg-date { font-size: 12.5px; color: var(--ink3); flex: none; }
.msg-body { padding: 2px 18px 14px 64px; font-size: 14.5px; }
.msg-body p { margin: 0 0 10px; white-space: pre-wrap; overflow-wrap: anywhere; }
.msg-body .quote { border-left: 2px solid var(--line); padding-left: 10px; color: var(--ink3); }
.msg-actions { display: flex; gap: 6px; margin-top: 12px; align-items: center; }
.atts { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 12px; }
.att-card { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px 8px 8px; min-width: 240px; }
.att-ic { color: #fff; font-size: 11px; font-weight: 700; border-radius: 6px; padding: 8px 6px; }
.att-meta { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.att-meta strong { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.att-meta em { font-style: normal; font-size: 12px; color: var(--ink3); }
.reply-bar { display: flex; gap: 10px; padding: 12px 24px 16px; border-top: 1px solid var(--line); }

/* Right rail */
.rail { width: 56px; flex: none; display: flex; flex-direction: column; align-items: center; gap: 4px; padding-top: 8px; position: relative; }
.rail-btn { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--ink2); }
.rail-btn:hover, .rail-btn.on { background: var(--hover); color: var(--accent); }
.rail-panel { position: absolute; right: 60px; top: 8px; width: 290px; background: var(--panel); border-radius: 14px; box-shadow: var(--shadow); padding: 14px; z-index: 40; }
.rail-head { display: flex; align-items: center; justify-content: space-between; font-weight: 600; margin-bottom: 10px; }
.minical strong { font-size: 13.5px; }
.cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; margin: 10px 0; text-align: center; font-size: 12px; }
.cal-grid .dow { color: var(--ink3); font-weight: 600; }
.cal-grid .day { padding: 5px 0; border-radius: 50%; }
.cal-grid .day.today { background: var(--accent); color: #fff; font-weight: 700; }
.cal-ev { display: flex; align-items: center; gap: 8px; font-size: 13px; padding: 4px 0; }
.notes { display: flex; flex-direction: column; gap: 8px; }
.note { background: #fef7e0; color: #1f1f1f; border: 1px solid #f0e0b0; border-radius: 8px; padding: 8px 10px; font-size: 13px; display: flex; justify-content: space-between; gap: 6px; align-items: flex-start; }
.task { display: flex; gap: 8px; font-size: 13.5px; align-items: center; }
.task.done { text-decoration: line-through; color: var(--ink3); }

/* Compose */
.composes { position: fixed; right: 76px; bottom: 0; display: flex; gap: 12px; align-items: flex-end; z-index: 80; }
.compose { width: 520px; max-width: calc(100vw - 32px); background: var(--panel); border-radius: 12px 12px 0 0; box-shadow: var(--shadow); display: flex; flex-direction: column; overflow: hidden; max-height: calc(100vh - 80px); }
.compose.max { width: min(860px, calc(100vw - 120px)); }
.compose.min { flex-direction: row; align-items: center; border-radius: 10px; margin-bottom: 12px; padding: 0 6px 0 0; width: 300px; }
.compose-title { flex: 1; text-align: left; padding: 12px 14px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compose-head { background: #f2f6fc; color: var(--ink); display: flex; align-items: center; padding: 6px 6px 6px 14px; font-weight: 500; font-size: 13.5px; }
[data-theme="dark"] .compose-head { background: #2f3336; }
.compose-head span:first-child { flex: 1; }
.compose-head-btns { display: flex; }
.compose-head-btns .icon-btn { color: var(--ink2); }
.compose-fields { padding: 0 4px; position: relative; }
.cf-row { display: flex; align-items: center; border-bottom: 1px solid var(--line); padding: 0 12px; gap: 8px; position: relative; }
.cf-row input { flex: 1; border: 0; outline: 0; padding: 9px 0; background: none; min-width: 0; }
.cc-links { display: flex; gap: 8px; font-size: 13px; }
.cc-links button { color: var(--ink3); }
.cc-links button:hover { color: var(--accent); }
.suggest { position: absolute; left: 8px; right: 8px; top: 40px; }
.compose-body { flex: 1; min-height: 220px; border: 0; outline: 0; resize: none; padding: 12px 16px; background: none; }
.compose.max .compose-body { min-height: 380px; }
.compose-foot { display: flex; align-items: center; gap: 10px; padding: 10px 14px; position: relative; }
.send-split { display: flex; position: relative; }
.send-split .send { border-radius: 20px 0 0 20px; padding: 8px 22px; }
.send-split .caret { border-radius: 0 20px 20px 0; border-left: 1px solid rgba(255,255,255,.4); padding: 8px 10px; }
.fmt-btns { display: flex; gap: 2px; color: var(--ink2); }
.fmt-btns button { width: 30px; height: 30px; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; }
.fmt-btns button:hover { background: var(--hover); }
.draft-note { margin-left: auto; font-size: 12px; color: var(--ink3); }
.suggest { background: var(--panel); box-shadow: var(--shadow); border-radius: 10px; z-index: 5; overflow: hidden; }
.suggest button { display: flex; gap: 10px; align-items: center; width: 100%; text-align: left; padding: 8px 12px; }
.suggest button:hover { background: var(--hover); }
.suggest strong { display: block; font-size: 13.5px; }
.suggest em { display: block; font-style: normal; font-size: 12px; color: var(--ink3); }

/* Toasts + overlay */
.toasts { position: fixed; left: 24px; bottom: 24px; display: flex; flex-direction: column; gap: 8px; z-index: 100; }
.toast { background: #1f1f1f; color: #e3e3e3; border-radius: 8px; padding: 12px 10px 12px 18px; display: flex; align-items: center; gap: 18px; box-shadow: var(--shadow); font-size: 14px; animation: rise .18s ease-out; }
.toast button { color: #a8c7fa; font-weight: 600; padding: 4px 8px; }
@keyframes rise { from { transform: translateY(8px); opacity: 0; } }
.overlay { position: fixed; inset: 0; background: rgba(20,24,28,.45); z-index: 90; display: flex; align-items: center; justify-content: center; padding: 16px; }
.shortcuts { background: var(--panel); border-radius: 16px; padding: 24px 28px; width: 420px; max-width: 100%; box-shadow: var(--shadow); }
.shortcuts h2 { margin: 0 0 14px; font-weight: 500; }
.sc-grid { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; max-height: 50vh; overflow-y: auto; }
.sc-row { display: flex; align-items: center; gap: 14px; font-size: 13.5px; }
kbd { background: var(--hover); border: 1px solid var(--line); border-radius: 6px; padding: 2px 9px; font-family: inherit; font-size: 12.5px; min-width: 52px; text-align: center; }

/* Responsive */
@media (max-width: 1100px) { .rail { display: none; } }
@media (max-width: 860px) {
  .tb-left { min-width: 0; }
  .brand-name { display: none; }
  .hide-sm { display: none; }
  .sidebar { position: fixed; z-index: 85; top: 0; bottom: 0; left: 0; background: var(--bg); padding-top: 64px; box-shadow: var(--shadow); margin-left: -280px; width: 280px; }
  .sidebar.mopen { margin-left: 0; }
  .sidebar.collapsed { margin-left: -280px; }
  .sidebar.collapsed.mopen { margin-left: 0; }
  .body { padding-right: 0; }
  .row .sender { width: 110px; }
  .imp { display: none; }
  .row .subj-snip .snip { display: none; }
  .thread-head, .msgs { padding-left: 14px; padding-right: 14px; }
  .msg-body { padding-left: 14px; }
  .composes { right: 0; left: 0; justify-content: center; }
  .compose { width: 100%; max-width: 100%; border-radius: 0; max-height: 92vh; }
  .tb-hint { max-width: 30vw; }
  .cat em { display: none; }
  .cat { min-width: 0; padding: 12px 14px 10px; }
}
@media print { .topbar, .sidebar, .rail, .toolbar, .reply-bar, .composes, .toasts { display: none !important; } .main { border-radius: 0; } }

