args.command:
dev-browser <<'EOF'
const page = await browser.getPage("mail");
await page.goto("http://127.0.0.1:9333/");
await page.waitForTimeout(1200);
await page.setViewport({ width: 390, height: 844 });
await page.waitForTimeout(800);
const m1 = await page.screenshot({ fullPage: false });
await saveScreenshot(m1, "mobile.png");
console.log("SHOT mobile saved");
await page.setViewport({ width: 1440, height: 900 });
await page.evaluate(() => { document.documentElement.dataset.theme = "dark"; });
await page.waitForTimeout(600);
const m2 = await page.screenshot({ fullPage: false });
await saveScreenshot(m2, "dark.png");
console.log("SHOT dark saved");
await page.evaluate(() => { document.documentElement.dataset.theme = "light"; });
console.log("DONE");
EOF

